/* Human Matrix 0.15 — Incarnation Cross, planet meanings, line fixation marks,
 * simpler center texts. Cross names and gate quartets follow Bunnell / Ra Uru Hu,
 * «Наука о Дифференциации», section 8; planets — section 1. */
window.HM_CROSSES={"intro": {"what": "Инкарнационный крест — это сводная тема вашей жизни, собранная из четырёх самых весомых активаций карты: Солнца и Земли Личности (сознательная сторона) и Солнца и Земли Дизайна (бессознательная, телесная сторона). На Мандале эти четверо ворот стоят друг напротив друга парами и вместе образуют крест. Он описывает предназначение — ту роль и тот вклад, который человек естественным образом вносит в целое; ни один крест не важнее другого. Крест не включается сам собой и не «назначается» сверху: он раскрывается тогда, когда человек живёт собой и принимает решения по своей Стратегии и Авторитету. Поэтому читать его отдельно от Стратегии и Авторитета бессмысленно — без них крест остаётся красивым описанием, а с ними становится живым путём.", "angles": {"right": "Правоугольный крест — путь личной судьбы. Человек проживает свою тему как бы для себя, через собственный опыт, а встречи с другими случаются в нужный момент и не определяют его путь целиком. Его дают профили 1/3, 1/4, 2/4, 2/5, 3/5, 3/6 и 4/6 — большинство людей.", "juxtaposition": "Крест Джакстапозиции — фиксированная, очень определённая судьба: человек идёт своей узкой, «собственной» колеёй, и его тема проявляется особенно последовательно. Он связан только с профилем 4/1, который стоит между личной и трансперсональной геометрией.", "left": "Левоугольный крест — трансперсональная судьба: путь разворачивается через встречи и связи с другими людьми, и то, что человек получает и отдаёт в этих связях, и есть его предназначение. Его дают профили 5/1, 5/2, 6/2 и 6/3."}, "plain": "Ваш крест — это то, ради чего вы здесь и что у вас получается вкладывать в мир, когда вы живёте по-своему. Узнать его по названию легко, а прожить — значит просто следовать своей Стратегии и Авторитету день за днём."}, "quarters": {"initiation": {"name": "Четверть Инициации", "theme": "Цель реализуется через Ум", "text": "Первая четверть, царство Альционы; её мистическая тема — «свидетель возвращается». Здесь предназначение раскрывается через мышление, учёбу, осмысление, объяснение и общение — через всё, что делает ум живым в теле. Когда ум перестаёт спорить с формой и доверяет ей, человек перестаёт пытаться быть кем-то другим; в этой четверти лежат шесть из семи ворот Солнечного сплетения и Канал Инициации."}, "civilization": {"name": "Четверть Цивилизации", "theme": "Цель реализуется через Форму", "text": "Вторая четверть, царство Дубхе; мистическая тема — «из родовых путей в дом». Здесь идеи, зародившиеся в уме, обретают форму: строятся структуры, сообщества, дома и цивилизации, в которых каждый может расти, а навыки совершенствуются на пользу целому. Сюда попадают все одиннадцать ворот Горлового центра — предназначение реализуется через проявление, через движение духа в форме."}, "duality": {"name": "Четверть Дуальности", "theme": "Цель реализуется через Отношения", "text": "Третья четверть, царство Юпитера; мистическая тема — «мера меры». Это самая земная и человечная четверть: здесь мы выходим из обособленности и обнаруживаем потребность друг в друге, и «двое становятся одним». Цель реализуется через соединение, выбор партнёра и продолжение рода; здесь лежат Канал Открытий и Интимности и все семь ворот Селезёнки."}, "mutation": {"name": "Четверть Мутации", "theme": "Цель реализуется через Трансформацию", "text": "Четвёртая четверть, царство Сириуса; мистическая тема — «принятие смерти». Здесь прожитый цикл подходит к завершению: опыт взвешивается, проверяется, и то, что выдержало проверку, готовится к передаче следующему поколению. Цель достигается раскрытием полного потенциала трансформации и осознанности; через эту четверть идёт большая часть Сакральной энергии и давления Корня."}}, "gates": {"1": {"quarter": "mutation", "right": {"name": "Сфинкса 4", "gates": [1, 2, 7, 13], "desc": "Творческие индивидуальности, стремящиеся создать нечто, что выразит и закрепит их собственное направление; своим примером поддерживают направление перемен."}, "juxtaposition": {"name": "Самовыражения", "gates": [1, 2, 4, 49], "desc": "Социально приспособленные люди, твёрдо стоящие на своих творческих и революционных ответах на вопросы, которые ещё никто не задал."}, "left": {"name": "Вызова 2", "gates": [1, 2, 4, 49], "desc": "Притягивают общество, но созданы защищать непохожесть; настойчиво требуют не вмешиваться в любую форму, чтобы сохранить её уникальность."}}, "2": {"quarter": "civilization", "right": {"name": "Сфинкса 2", "gates": [2, 1, 13, 7], "desc": "Влиятельные доверенные лица, соединяющие чувство прекрасного с глубоким откликом на материальные нужды людей; через связь с прошлым меняют материальный курс коллектива."}, "juxtaposition": {"name": "Водителя", "gates": [2, 1, 49, 4], "desc": "Полностью сосредоточены на своём направлении и принципах и увлекают других за собой; даже короткая встреча с ними может изменить ваш курс."}, "left": {"name": "Вызова", "gates": [2, 1, 49, 4], "desc": "Кажется, они всегда идут наперекор общему курсу, следуя своему; умеют выдернуть других из привычной колеи."}}, "3": {"quarter": "initiation", "right": {"name": "Законов", "gates": [3, 50, 60, 56], "desc": "Творчески создают, формируют и меняют законы и ценности, которые определяют, как мы живём друг с другом, и приносят обществу порядок."}, "juxtaposition": {"name": "Мутации", "gates": [3, 50, 41, 31], "desc": "Ищут возможность изменить несправедливые правила и через это утвердить своё влияние в процессе перемен."}, "left": {"name": "Желаний", "gates": [3, 50, 41, 31], "desc": "Притягательные и влиятельные люди с альтруистической жилкой, которые всё время ищут, как сделать жизнь других лучше, и видят новый порядок вещей."}}, "4": {"quarter": "duality", "right": {"name": "Объяснений 3", "gates": [4, 49, 23, 43], "desc": "Их задача — объяснять революционные и принципиальные решения: непроверенное индивидуальное знание нуждается в разъяснении и повторных озарениях, пропущенных через логику."}, "juxtaposition": {"name": "Формулирования", "gates": [4, 49, 8, 14], "desc": "Вдохновляют умением создавать формулы и видеть необычные закономерности, способные укрепить новое направление."}, "left": {"name": "Революции 2", "gates": [4, 49, 8, 14], "desc": "На них возлагают ожидание найти практические причины и ресурсы, без которых революция не начнётся."}}, "5": {"quarter": "mutation", "right": {"name": "Сознания 4", "gates": [5, 35, 64, 63], "desc": "Создают собственный импульс к росту, следуя своему потоку; сознание для них — глубокое согласие с естественным ритмом."}, "juxtaposition": {"name": "Привычек", "gates": [5, 35, 47, 22], "desc": "Люди привычки и постоянства, на чей ритм трудно повлиять; их устойчивые ритуалы приносят в жизнь последовательность."}, "left": {"name": "Разделения 2", "gates": [5, 35, 47, 22], "desc": "Открытые любви люди, которые ищут смысл прошлого, отделяясь от неработающих схем и отношений, чтобы увидеть — и обновить — красоту больших узоров жизни."}}, "6": {"quarter": "duality", "right": {"name": "Рая 3", "gates": [6, 36, 12, 11], "desc": "Опыт конфликтов и кризисов помогает им сохранять близкие отношения; мудрость приходит через утрату невинности."}, "juxtaposition": {"name": "Конфликта", "gates": [6, 36, 15, 10], "desc": "Соединяют утрату невинности с девизом «жизнь продолжается» и создают плодородную почву для товарищества; дружба и любовь рождаются в кризисе."}, "left": {"name": "Земного Плана 2", "gates": [6, 36, 15, 10], "desc": "Наслаждаются своим делом и увлекают нас материальным миром, чтобы у нас всегда было то, что нужно для любви в этом мире."}}, "7": {"quarter": "duality", "right": {"name": "Сфинкса 3", "gates": [7, 13, 2, 1], "desc": "Влиятельные лидеры, чья высказанная логика и внимание к прошлому помогают вести людей к безопасному будущему."}, "juxtaposition": {"name": "Взаимодействия", "gates": [7, 13, 23, 43], "desc": "Всё время ищут, как проявить себя лидером — влиятельным, но не поддающимся влиянию; ведут через принятие разнообразия."}, "left": {"name": "Масок 2", "gates": [7, 13, 23, 43], "desc": "На них проецируют ожидание мудрого и практичного руководства; влиятельные агенты перемен, лучше всего действующие в должности или «под маской» — как генерал или врач."}}, "8": {"quarter": "civilization", "right": {"name": "Заразительности 2", "gates": [8, 14, 30, 29], "desc": "Увлекают своим примером: вкладывают ресурсы в будущую безопасность и благополучие, и этот пример воспитывает других."}, "juxtaposition": {"name": "Вклада", "gates": [8, 14, 55, 59], "desc": "Последовательно стремятся помогать обществу своими творческими и душевными, близкими способностями."}, "left": {"name": "Неуверенности", "gates": [8, 14, 55, 59], "desc": "Проходят через неуверенность, когда энергия превращается в форму; им нужны верный дух и верные материальные ресурсы."}}, "9": {"quarter": "mutation", "right": {"name": "Планирования 4", "gates": [9, 16, 40, 37], "desc": "Их энтузиазм уравновешен вниманием к нужным деталям; большое — планы, сделки, таланты — растёт само, когда всё продумано и подкреплено."}, "juxtaposition": {"name": "Фокуса", "gates": [9, 16, 64, 63], "desc": "С воодушевлением помогают другим сосредоточиться на том, что важно для коллектива, — выделяя возможное будущее общества и концентрируясь на нём."}, "left": {"name": "Идентификации 2", "gates": [9, 16, 64, 63], "desc": "Отождествляют себя с тем, во что вкладывают навыки, и обретают душевное равновесие, зная, что все нужные ресурсы на месте."}}, "10": {"quarter": "mutation", "right": {"name": "Чаши Любви 4", "gates": [10, 15, 46, 25], "desc": "Оставаясь собой и любя свою непохожесть, они обогащают индивидуальное поведение и подталкивают мир к любви."}, "juxtaposition": {"name": "Поведения", "gates": [10, 15, 18, 17], "desc": "Критичный и находчивый человек, стремящийся произвести верное впечатление своим поведением, наводя порядок в чужом поведении или бросая ему вызов."}, "left": {"name": "Предотвращения 2", "gates": [10, 15, 18, 17], "desc": "Одновременно сдерживают и освобождают: вносят поправки, стараясь предупредить нездоровые поступки людей и общества до того, как они случатся."}}, "11": {"quarter": "mutation", "right": {"name": "Рая 4", "gates": [11, 12, 6, 36], "desc": "Люди философского склада, обучающие других природе опыта и чувств — возможно, через музыку или поэзию."}, "juxtaposition": {"name": "Идей", "gates": [11, 12, 46, 25], "desc": "Несут перемены, собирая всеобщие идеи; могут стать важными учителями, часто последовательно держатся одного направления."}, "left": {"name": "Образования 2", "gates": [11, 12, 46, 25], "desc": "Люди мира, щедрости и просвещения, стремящиеся высказать трудновыразимые идеи о человеческом опыте; для них обучение — самое глубокое человеческое занятие."}}, "12": {"quarter": "civilization", "right": {"name": "Рая 2", "gates": [12, 11, 36, 6], "desc": "Уверенные в себе люди, превращающие утрату невинности в искусство; умеют выражать любовь и кризис через поэзию и музыку."}, "juxtaposition": {"name": "Артикуляции", "gates": [12, 11, 25, 46], "desc": "Сильный оратор или преподаватель с редким даром воздействовать голосом, который заражает других и подталкивает их к собственной индивидуальности."}, "left": {"name": "Образования", "gates": [12, 11, 25, 46], "desc": "Сильные лекторы, ищущие благодарную аудиторию; посвящают себя просвещению многих и через это способствуют глобальным переменам."}}, "13": {"quarter": "initiation", "right": {"name": "Сфинкса", "gates": [13, 7, 1, 2], "desc": "Люди собственного направления, которые по-своему запоминают пережитое и несут яркое, живое прошлое в будущее."}, "juxtaposition": {"name": "Слушания", "gates": [13, 7, 43, 23], "desc": "Прирождённые слушатели и хранители чужих тайн; свои прозрения они часто выражают через творчество."}, "left": {"name": "Масок", "gates": [13, 7, 43, 23], "desc": "Их объяснения и откровения способны направлять и менять других; лучше всего они действуют в роли — «под маской», как врач в белом халате."}}, "14": {"quarter": "mutation", "right": {"name": "Заразительности 4", "gates": [14, 8, 29, 30], "desc": "Вносят мощный вклад в общество, накапливая и удерживая ресурсы, власть или деньги; разумно использованные средства становятся топливом для роста человечества."}, "juxtaposition": {"name": "Усиления", "gates": [14, 8, 59, 55], "desc": "Их меланхоличный дух тесно связан с финансовой надёжностью; создают прочное основание из ресурсов, которые возвращаются и усиливают других."}, "left": {"name": "Неуверенности 2", "gates": [14, 8, 59, 55], "desc": "Понимая финансовую неуверенность других, помогают обеспечить необходимое; близость возникает или крепнет через материальную надёжность — реальную или обещанную."}}, "15": {"quarter": "civilization", "right": {"name": "Чаши Любви 2", "gates": [15, 10, 25, 46], "desc": "Естественно заботятся о благополучии человечества; зная своё место, приносят в поток жизни разнообразие."}, "juxtaposition": {"name": "Крайностей", "gates": [15, 10, 17, 18], "desc": "Живут в собственном, часто крайнем ритме, который редко совпадает с чужим, и сами того не замечая высвечивают то, что нужно исправить."}, "left": {"name": "Предотвращения", "gates": [15, 10, 17, 18], "desc": "Как будто всегда натыкаются на то, что не работает; их дар — бережно вести общество, не давая ему повторять прежние ошибки."}}, "16": {"quarter": "civilization", "right": {"name": "Планирования 2", "gates": [16, 9, 37, 40], "desc": "Энтузиасты, увлечённые точными решениями, хорошо сделанной работой и поиском логичного пути к прогрессу и мастерству."}, "juxtaposition": {"name": "Экспериментирования", "gates": [16, 9, 63, 64], "desc": "Влиятельные люди, умело выстраивающие сеть знакомств, чтобы с воодушевлением поддержать свой новый эксперимент."}, "left": {"name": "Идентификации", "gates": [16, 9, 63, 64], "desc": "Логически ориентированные люди, которые умеют привлекать других — чтобы поддержать или подтвердить свои навыки и проекты или просто купить их продукт."}}, "17": {"quarter": "initiation", "right": {"name": "Служения", "gates": [17, 18, 58, 52], "desc": "Логически понимают, что значит быть человеком; неудовлетворённость толкает их исправлять, перестраивать и служить людям."}, "juxtaposition": {"name": "Мнений", "gates": [17, 18, 38, 39], "desc": "Побуждают вас исследовать свой дух и свою цель; мнениями делятся щедро, а оспорить их непросто."}, "left": {"name": "Переворота", "gates": [17, 18, 38, 39], "desc": "Любят «наступать на мозоли» и вмешиваться, расшатывая статус-кво, чтобы подготовить людей к нужным исправлениям и более здоровому курсу."}}, "18": {"quarter": "duality", "right": {"name": "Служения 3", "gates": [18, 17, 52, 58], "desc": "Участвуют в непрерывном исправлении и улучшении мужских и женских, отцовских и материнских образцов; их мнения и поправки служат тому, чтобы даже хорошее стало лучше."}, "juxtaposition": {"name": "Исправления", "gates": [18, 17, 39, 38], "desc": "Мастера замечать изъяны в схеме или некомпетентность — у всех, кроме себя; способны превратить «Золушку» в принцессу."}, "left": {"name": "Переворота 2", "gates": [18, 17, 39, 38], "desc": "С еретическим взглядом или обезоруживающей невинностью всегда готовы задеть и бросить вызов тому, что не работает; знают, что помощь должна быть практичной."}}, "19": {"quarter": "mutation", "right": {"name": "Четырех Путей 4", "gates": [19, 33, 44, 24], "desc": "Чутки к правам людей и животных; социальные и духовные мотивы побуждают их обеспечивать базовые потребности других."}, "juxtaposition": {"name": "Потребностей", "gates": [19, 33, 1, 2], "desc": "Люди творческого склада с глубокой потребностью создавать красоту в жизни, которой будет радоваться их близкий круг."}, "left": {"name": "Очищения 2", "gates": [19, 33, 1, 2], "desc": "Понимают, что верное направление и согласие с собой и есть высшая красота, которая удовлетворяет их нужды, совершенствует опыт и ведёт к цели."}}, "20": {"quarter": "civilization", "right": {"name": "Спящего Феникса 2", "gates": [20, 34, 55, 59], "desc": "Вечно занятые притягательные люди, целиком поглощённые тем, что нужно сделать, или своим творческим процессом в ожидании будущих перемен."}, "juxtaposition": {"name": "Настоящего", "gates": [20, 34, 37, 40], "desc": "Их занятость служит роду, семье, паре и сообществу; внутри живёт тяга-толкай между нуждами общины и тем, на что хочется направить силы."}, "left": {"name": "Дуальности", "gates": [20, 34, 37, 40], "desc": "Производят впечатление и находят себя в деле; заключают сделки, создающие связи и взаимовыгодные союзы."}}, "21": {"quarter": "initiation", "right": {"name": "Напряжения", "gates": [21, 48, 38, 39], "desc": "Прирождённые хозяева границ, которым важно держать под контролем своё пространство и всех в нём; отлично наводят порядок и следят за ситуацией."}, "juxtaposition": {"name": "Контроля", "gates": [21, 48, 54, 53], "desc": "Твёрдо нацелены на свои амбиции и требуют для себя управляющей позиции — и благодаря этому способны запускать новое и вводить новшества."}, "left": {"name": "Попытки", "gates": [21, 48, 54, 53], "desc": "Честолюбивые агенты перемен, собирающие ценных людей для освоения новых горизонтов — в общинных, деловых или научных структурах."}}, "22": {"quarter": "initiation", "right": {"name": "Правления", "gates": [22, 47, 26, 45], "desc": "Знают своё место и правят с изяществом; главная их ответственность — обучать тех, кто под их началом, и лучше всего им, когда есть чем управлять."}, "juxtaposition": {"name": "Грациозности", "gates": [22, 47, 11, 12], "desc": "Социально чуткие, последовательные в своём принятии люди, сильные агенты мутации; любят искусство и умеют слушать."}, "left": {"name": "Информирования", "gates": [22, 47, 11, 12], "desc": "Меняют других силой слова: рассказывают всем о новом и непохожем и через обучение запускают перемены."}}, "23": {"quarter": "civilization", "right": {"name": "Объяснений 2", "gates": [23, 43, 49, 4], "desc": "Вечные «чужаки», которые раз за разом объясняют себя и свои необычные идеи, чтобы те вошли в чужой революционный или аналитический процесс."}, "juxtaposition": {"name": "Ассимиляции", "gates": [23, 43, 30, 29], "desc": "Увлечённая натура, повторяющая новую мысль до тех пор, пока она не станет привычной или её не примут готовые слушать друзья."}, "left": {"name": "Посвящения", "gates": [23, 43, 30, 29], "desc": "Потенциально большие учителя, готовые объяснять одно и то же много раз ради обучения и перемен; их всегда занимает, что будет дальше."}}, "24": {"quarter": "initiation", "right": {"name": "Четырех Путей", "gates": [24, 44, 19, 33], "desc": "Их путь развивает и сознание, и форму: снова и снова пересматривая мысли и понятия, они ищут ясности и ответов — «как, почему, что есть Бог?»."}, "juxtaposition": {"name": "Рационализации", "gates": [24, 44, 13, 7], "desc": "Яркие, умные и очень последовательные люди, ищущие связную линию между прошлым и будущим; умеют переводить индивидуальное знание на понятный язык логики и опыта."}, "left": {"name": "Инкарнации", "gates": [24, 44, 13, 7], "desc": "Особым образом связаны и с прошлым, и с будущим; когда живут в согласии со своей природой, могут глубоко повлиять на ваше направление."}}, "25": {"quarter": "initiation", "right": {"name": "Чаши Любви", "gates": [25, 46, 10, 15], "desc": "Носители ощущения всеобщей, надличной любви, которая выравнивает путь человечества и его потребность выживать и продолжать род."}, "juxtaposition": {"name": "Невинности", "gates": [25, 46, 58, 52], "desc": "Живут ради радости жизни и умеют убедить других, что в своей собственной природе можно чувствовать себя хорошо; жизнь как поиск счастья."}, "left": {"name": "Исцеления", "gates": [25, 46, 58, 52], "desc": "Берегут радость и качество жизни через любовь к ней и к здоровому телу; особенно чутки к тем, кто болеет, — созданы помогать другим или восстанавливать себя."}}, "26": {"quarter": "mutation", "right": {"name": "Правления 4", "gates": [26, 45, 47, 22], "desc": "Обаятельные люди, умеющие подать себя как лидера: избирательная память, личный контакт и обещание научить каждого лучшему завтра."}, "juxtaposition": {"name": "Трюкача", "gates": [26, 45, 6, 36], "desc": "Обладают природным даром продать что угодно неопытным и продвигают необычное."}, "left": {"name": "Конфронтации 2", "gates": [26, 45, 6, 36], "desc": "С грацией и острым чувством личной справедливости противостоят власти, которая пытается их ограничить; сильные натуры, не желающие меняться в угоду другим."}}, "27": {"quarter": "initiation", "right": {"name": "Неожиданного", "gates": [27, 28, 41, 31], "desc": "Неожиданные события естественным образом запускают их в новый виток жизни, и в итоге это питает их и расширяет сознание."}, "juxtaposition": {"name": "Заботы", "gates": [27, 28, 19, 33], "desc": "Живут заботой обо всём и обо всех, включая себя; их память, озарения и принципы вырастают из глубокой потребности."}, "left": {"name": "Выравнивания", "gates": [27, 28, 19, 33], "desc": "Умеют обернуть неожиданность на пользу и в момент перехода дать ей верное направление; помогают другим понять, с чем им по-настоящему по пути."}}, "28": {"quarter": "duality", "right": {"name": "Неожиданного 3", "gates": [28, 27, 31, 41], "desc": "Им внезапно приходится заботиться о ком-то или отвечать за что-то; найдя в этой борьбе свою цель, они становятся влиятельным примером."}, "juxtaposition": {"name": "Рисков", "gates": [28, 27, 33, 19], "desc": "Любители риска, которые рискуют ради того, что им нужно, или чтобы найти цель и смысл жизни."}, "left": {"name": "Выравнивания 2", "gates": [28, 27, 33, 19], "desc": "Вдумчивые люди, умеющие обратить неожиданность себе на пользу и готовые отпустить старое, чтобы настроиться на новое."}}, "29": {"quarter": "duality", "right": {"name": "Заразительности 3", "gates": [29, 30, 8, 14], "desc": "Говорят «да» новому — и близкому — опыту в стремлении исполнить обязательства и проживают опыт ради самого опыта."}, "juxtaposition": {"name": "Обязательств", "gates": [29, 30, 20, 34], "desc": "Всем существом стремятся сказать «да» одному обязательству; часто вдохновляют других примером безоглядной преданности делу."}, "left": {"name": "Индустрии 2", "gates": [29, 30, 20, 34], "desc": "Не осознают собственной огромной притягательной силы; взяв на себя верные обязательства, начинают светиться и упорно продолжают своё дело."}}, "30": {"quarter": "initiation", "right": {"name": "Заразительности", "gates": [30, 29, 14, 8], "desc": "Невольные орудия судьбы: появляются в чужой жизни и неожиданно меняют её через новый опыт, открытия и обучение."}, "juxtaposition": {"name": "Судеб", "gates": [30, 29, 34, 20], "desc": "Энергичный, упорный, притягательный человек, ведомый судьбой и одержимый желанием исполнить своё стремление; в нём есть потенциал мистического учителя."}, "left": {"name": "Индустрии", "gates": [30, 29, 34, 20], "desc": "Неутомимый «двигатель», который строит и связывает ради прогресса человечества и хочет прочувствовать эмоциональную глубину каждого нового опыта."}}, "31": {"quarter": "civilization", "right": {"name": "Неожиданного 2", "gates": [31, 41, 27, 28], "desc": "Обладают врождённой способностью притягивать внимание коллектива и неожиданно становятся лидерами или героями; их опекающее влияние проявляется внезапно."}, "juxtaposition": {"name": "Влияния", "gates": [31, 41, 24, 44], "desc": "Естественно влиятельные и последовательные люди, сознательно убеждающие других своим мышлением, новым опытом и памятью."}, "left": {"name": "Альфы", "gates": [31, 41, 24, 44], "desc": "Сильные лидеры, влияющие на других тем, что решают вопросы выживания на уровне ума; ищут практические решения, которые обеспечат будущее."}}, "32": {"quarter": "duality", "right": {"name": "Майи 3", "gates": [32, 42, 62, 61], "desc": "Внутреннее знание и умение работать с деталями позволяют им верно оценивать и поддерживать материальный рост, созревание и расширение."}, "juxtaposition": {"name": "Сохранения", "gates": [32, 42, 56, 60], "desc": "Осторожные, не склонные к риску люди, ценящие непрерывность; берегут ресурсы, чтобы обеспечить выживание будущих поколений."}, "left": {"name": "Ограничений 2", "gates": [32, 42, 56, 60], "desc": "Воспринимают непостоянство как ограничение и оценивают продукты и дела по их практичности и способности выдержать проверку временем."}}, "33": {"quarter": "civilization", "right": {"name": "Четырех Путей 2", "gates": [33, 19, 24, 44], "desc": "Уединяются, чтобы осмыслить опыт, прежде чем поделиться выводами, воспоминаниями или принципами; им нужно своё неприкосновенное пространство."}, "juxtaposition": {"name": "Ретрита", "gates": [33, 19, 2, 1], "desc": "Нуждаются в красоте жизни; их эстетика уединения начинается с достатка еды и крыши над головой — с собственного пространства."}, "left": {"name": "Очищения", "gates": [33, 19, 2, 1], "desc": "Знают, что мало просто иметь и охранять дом: жизнь богаче, когда всё сделано красиво; красота, которая лечит."}}, "34": {"quarter": "mutation", "right": {"name": "Спящего Феникса 4", "gates": [34, 20, 59, 55], "desc": "Притягательные люди с огромной личной силой, вовлекающие других в своё дело; сила и близость, направленные духом, служат людям."}, "juxtaposition": {"name": "Силы", "gates": [34, 20, 40, 37], "desc": "Их занятость — это чистое выражение притягательной силы ради поддержки сообщества: ведущий сцены или деловой руководитель, заключающий сделки."}, "left": {"name": "Дуальности 2", "gates": [34, 20, 40, 37], "desc": "Соединяют главную дилемму человечества — индивидуальную силу и самость с ответственностью перед общиной; занятость в равновесии с любовью к поддержке других."}}, "35": {"quarter": "civilization", "right": {"name": "Сознания 2", "gates": [35, 5, 63, 64], "desc": "Те, кто «там был, это делал и всё об этом знает»; чутки к переменам, зовут вас за собой и всегда готовы пробовать новые способы."}, "juxtaposition": {"name": "Опыта", "gates": [35, 5, 22, 47], "desc": "Влиятельные люди, делящиеся опытом, который меняет сознание других; для них опыт — это всё."}, "left": {"name": "Разделения", "gates": [35, 5, 22, 47], "desc": "С изяществом видят потребность каждого жить по-своему внутри общества, принимая разные толкования опыта, который обычно разводит людей."}}, "36": {"quarter": "initiation", "right": {"name": "Рая", "gates": [36, 6, 11, 12], "desc": "Ищут волнения и нового опыта и в итоге — через утрату невинности — приходят к мудрости и изяществу."}, "juxtaposition": {"name": "Кризиса", "gates": [36, 6, 10, 15], "desc": "Любят себя и людей и лучше всех изучают то, как другие ведут себя в кризисе, поднимая опыт, в том числе чувственный, на новую ступень."}, "left": {"name": "Земного Плана", "gates": [36, 6, 10, 15], "desc": "Свидетели земной жизни во всём её размахе — от прекрасного до уродливого, — способные показать, что за этим есть свет, дух и пробуждение."}}, "37": {"quarter": "initiation", "right": {"name": "Планирования", "gates": [37, 40, 9, 16], "desc": "Строят и укрепляют общие институты, используя деловые навыки и поддерживая совместную жизнь; соединяют людей, чтобы создать нечто большее."}, "juxtaposition": {"name": "Сделок", "gates": [37, 40, 5, 35], "desc": "Участливые и обаятельные «торговцы», которым трудно отказать; мастера создавать новые условия или смягчать старые ради прогресса сообщества."}, "left": {"name": "Миграции", "gates": [37, 40, 5, 35], "desc": "Завершив общий проект, они снова идут к новым пастбищам — к следующей территории и новому опыту; в них корни прогресса."}}, "38": {"quarter": "mutation", "right": {"name": "Напряжения 4", "gates": [38, 39, 48, 21], "desc": "Люди творческой глубины, понимающие, что жизнь — это борьба, и именно в борьбе проявляются дух и цель, придающие ей ценность."}, "juxtaposition": {"name": "Оппозиции", "gates": [38, 39, 57, 51], "desc": "Индивидуалисты с адреналиновой энергией, которые интуитивно провоцируют, возражают или ошеломляют доводами в ответ на ваши требования и мнения."}, "left": {"name": "Индивидуализма 2", "gates": [38, 39, 57, 51], "desc": "Чистые индивидуалисты, всегда находящиеся в процессе становления собой и в ответ встряхивающие, напрягающие или меняющие вас."}}, "39": {"quarter": "civilization", "right": {"name": "Напряжения 2", "gates": [39, 38, 21, 48], "desc": "Их внутреннее напряжение просится наружу и пробуждает в других талант, лидерство, цель и дух; любят «наступать на мозоли»."}, "juxtaposition": {"name": "Провокаций", "gates": [39, 38, 51, 57], "desc": "Сильные, но переменчивые индивидуалисты, задевающие других шоком на глубоком уровне; понимают творческую ценность своей меланхолии."}, "left": {"name": "Индивидуализма", "gates": [39, 38, 51, 57], "desc": "Силы мутации, удивляющие интуитивным знанием и своей непохожестью, но сами мало поддающиеся чужому влиянию."}}, "40": {"quarter": "duality", "right": {"name": "Планирования 3", "gates": [40, 37, 16, 9], "desc": "При нужной поддержке и правильной договорённости у них есть навыки, логика и внимание к деталям, чтобы построить то, что нужно сообществу."}, "juxtaposition": {"name": "Отрицания", "gates": [40, 37, 35, 5], "desc": "Их работа — упрямо говорить «нет» любой сделке, пока она не станет правильной, и притормаживать безудержную гонку коллективного прогресса."}, "left": {"name": "Миграции 2", "gates": [40, 37, 35, 5], "desc": "Переезжают и перемещаются, желая принести развитие и перемены в следующее сообщество."}}, "41": {"quarter": "mutation", "right": {"name": "Неожиданного 4", "gates": [41, 31, 28, 27], "desc": "Неожиданно оказываются лидерами, задающими новые тенденции в заботе или в поиске цели."}, "juxtaposition": {"name": "Фантазии", "gates": [41, 31, 44, 24], "desc": "Влиятельные люди, особенно сильные там, где ценятся предчувствие будущих тенденций и мечты о нём; склонны давать волю фантазиям и виртуальным мирам."}, "left": {"name": "Альфы 2", "gates": [41, 31, 44, 24], "desc": "Увлекают других мечтами и фантазиями в ожидании счастливого момента, чтобы привести их к «земле обетованной» — к тому, что кажется новым и лучшим."}}, "42": {"quarter": "initiation", "right": {"name": "Майи", "gates": [42, 32, 61, 62], "desc": "Задают тенденции, опираясь на верно оценённые детали; несут рост и, завершая один цикл, готовят почву для следующего."}, "juxtaposition": {"name": "Завершения", "gates": [42, 32, 60, 56], "desc": "Сосредоточены на том, чтобы довести начатое до конца, — как марафонец, который финиширует, когда остальные уже разошлись."}, "left": {"name": "Ограничений", "gates": [42, 32, 60, 56], "desc": "Знают, что можно довести до конца, а что нет; принимают границы как условие материального успеха и умелого обращения с ресурсами."}}, "43": {"quarter": "mutation", "right": {"name": "Объяснений 4", "gates": [43, 23, 4, 49], "desc": "Их знание несёт революционный заряд; понимание начинается с того, что они ясно и логично объясняют своё прозрение."}, "juxtaposition": {"name": "Озарения", "gates": [43, 23, 29, 30], "desc": "Глубоко хотят выразить свои уникальные прозрения и способны действенно повлиять на тех, кто готов и хочет слушать."}, "left": {"name": "Посвящения 2", "gates": [43, 23, 29, 30], "desc": "Посвящают себя тому, чтобы передавать свои прозрения другим, — как тихое преобразующее действие, повышающее действенность общества."}}, "44": {"quarter": "duality", "right": {"name": "Четырех Путей 3", "gates": [44, 24, 33, 19], "desc": "Люди рода с острым чутьём, инстинктивной памятью о прошлом и чуткостью к благополучию других; глубоко заботятся о жизнеспособности семейного дела."}, "juxtaposition": {"name": "Бдительности", "gates": [44, 24, 7, 13], "desc": "Бдительные инстинктивные провидцы, ощущающие, откуда мы пришли и куда движемся; к ним стоит прислушиваться."}, "left": {"name": "Инкарнации 2", "gates": [44, 24, 7, 13], "desc": "Глубоко связаны с прошлым и связывают с ним нас; без конца размышляют о смысле воплощения и о том, что нужно для выживания."}}, "45": {"quarter": "civilization", "right": {"name": "Правления 2", "gates": [45, 26, 22, 47], "desc": "Люди, которым естественно предлагают власть; в современном мире это, например, председатель совета в корпорации."}, "juxtaposition": {"name": "Владения", "gates": [45, 26, 36, 6], "desc": "Влиятельные люди, способные взять на себя руководство сообществом и ответственность за него в кризис и в конфликте."}, "left": {"name": "Конфронтации", "gates": [45, 26, 36, 6], "desc": "Распоряжаются ресурсами рода в трудные времена и с позиции силы бросают вызов тем, кто хотел бы править, отстаивая свои требования."}}, "46": {"quarter": "duality", "right": {"name": "Чаши Любви 3", "gates": [46, 25, 15, 10], "desc": "Полностью «воплощённые» люди, живущие в своём теле и наслаждающиеся чувственной стороной отношений; жизнь ради самой жизни."}, "juxtaposition": {"name": "Интуитивной Прозорливости", "gates": [46, 25, 52, 58], "desc": "Умеют оказаться в нужном месте в нужное время и понимают, что верные обязательства и добросовестный труд приводят к удаче; быть живым — большая радость."}, "left": {"name": "Исцеления 2", "gates": [46, 25, 52, 58], "desc": "Исцеляют или исцеляются спонтанно, через связь с безличной, всеобщей любовью; редкий светлый дар, который оживает в преданной связи с другими."}}, "47": {"quarter": "duality", "right": {"name": "Правления 3", "gates": [47, 22, 45, 26], "desc": "С изяществом несут прошлое вперёд: выборочно берут традиции и уроки опыта и на этом основании утверждают своё право управлять."}, "juxtaposition": {"name": "Подавления", "gates": [47, 22, 12, 11], "desc": "Используют понимание прошлого, чтобы ясно сформулировать и продвинуть новую идею или заменить устаревшее понимание."}, "left": {"name": "Информирования 2", "gates": [47, 22, 12, 11], "desc": "Социально умелые люди, которые через прошлое вдохновляют и привлекают внимание к тяжёлому положению угнетённых; их информирование похоже на искусство."}}, "48": {"quarter": "duality", "right": {"name": "Напряжения 3", "gates": [48, 21, 39, 38], "desc": "Обладают врождённой интуитивной глубиной: понимают проблему и пробуждают нужные навыки, дух и цели, чтобы найти рабочее решение."}, "juxtaposition": {"name": "Глубины", "gates": [48, 21, 53, 54], "desc": "Влиятельные люди, применяющие глубину понимания для своих целей, расширения круга и возможности учить и помогать другим преодолеть ощущение несостоятельности и начать новое."}, "left": {"name": "Попытки 2", "gates": [48, 21, 53, 54], "desc": "Реализуют свою глубину через желание держать всё под контролем; их девиз — «я сделаю это сам»."}}, "49": {"quarter": "initiation", "right": {"name": "Объяснений", "gates": [49, 4, 43, 23], "desc": "Странствующий провозвестник принципов: напоминает, что базовые потребности для выживания должны быть закрыты у всех, и остро чувствует нуждающихся."}, "juxtaposition": {"name": "Принципов", "gates": [49, 4, 14, 8], "desc": "Революционеры, опередившие своё время и твёрдо стоящие на принципах — часто на правах человека; ради сильного союзника готовы договориться с кем угодно."}, "left": {"name": "Революции", "gates": [49, 4, 14, 8], "desc": "Революционер, который понимает: на голодный желудок мир не радует. Его тема — чтобы имеющие делились с теми, у кого нет."}}, "50": {"quarter": "duality", "right": {"name": "Законов 3", "gates": [50, 3, 56, 60], "desc": "Создают, приспосабливают и оценивают законы и ценности ради нашей эволюции; для них законотворчество — внутренний творческий процесс, опирающийся на инстинкт выживания в эпоху перемен."}, "juxtaposition": {"name": "Ценностей", "gates": [50, 3, 31, 41], "desc": "Влиятельные люди, использующие возможности, чтобы смягчить суровость правил и сделать наказание соразмерным проступку."}, "left": {"name": "Желаний 2", "gates": [50, 3, 31, 41], "desc": "Утописты, стремящиеся выйти за рамки привычных ценностей; бросают вызов культурным и религиозным нормам, показывая, какой могла бы быть система."}}, "51": {"quarter": "initiation", "right": {"name": "Проникновения", "gates": [51, 57, 54, 53], "desc": "Застают врасплох и захватывают внимание точными интуитивными прозрениями; их идеи способны встряхнуть и изменить наше восприятие."}, "juxtaposition": {"name": "Шока", "gates": [51, 57, 61, 62], "desc": "Не дают нам стать слишком серьёзными и самоуверенными, удивляя деталями и внезапным интуитивным знанием."}, "left": {"name": "Глашатая", "gates": [51, 57, 61, 62], "desc": "Созданы встряхнуть тех, кто к этому готов и открыт переменам, — передавая детали, рождённые вдохновением и интуицией."}}, "52": {"quarter": "civilization", "right": {"name": "Служения 2", "gates": [52, 58, 17, 18], "desc": "Люди логики, несущие ответственность — и топливо — за то, чтобы схема, ведущая нас в будущее, была верной и исправленной."}, "juxtaposition": {"name": "Неподвижности", "gates": [52, 58, 21, 48], "desc": "Спокойно и радостно строят сети связей, создавая возможность влиять на других своей глубиной и решениями."}, "left": {"name": "Требований", "gates": [52, 58, 21, 48], "desc": "Призваны защищать общество, настаивая, чтобы решения были найдены, исправления сделаны, а договорённости подтверждены."}}, "53": {"quarter": "civilization", "right": {"name": "Проникновения 2", "gates": [53, 54, 51, 57], "desc": "Выглядят счастливыми в моменте, но чувствуют давление — быть признанными в начале нового — и интуитивно знают, как вовлечь в него других."}, "juxtaposition": {"name": "Начинаний", "gates": [53, 54, 42, 32], "desc": "Искатели, запускающие новые циклы и начинания; умеют оценить ценность людей и их навыков и непрерывность проекта."}, "left": {"name": "Циклов", "gates": [53, 54, 42, 32], "desc": "Доводят цикл перемен до зрелости и понимают, что неизменны только сами перемены."}}, "54": {"quarter": "mutation", "right": {"name": "Проникновения 4", "gates": [54, 53, 57, 51], "desc": "Люди пути «из грязи в князи», которых признают в иерархии; настроены на высшие, порой мистические силы."}, "juxtaposition": {"name": "Амбиций", "gates": [54, 53, 32, 42], "desc": "Влиятельные, но осторожные агенты перемен, движимые страхом неудачи и потребностью выполнить обязательства; им всегда мало, они стремятся к большему."}, "left": {"name": "Циклов 2", "gates": [54, 53, 32, 42], "desc": "Амбициозные люди, умеющие разжечь перемены на пользу себе, другим и целым народам, — благодаря преданности непрерывности, которая вырастает из каждого завершённого цикла."}}, "55": {"quarter": "initiation", "right": {"name": "Спящего Феникса", "gates": [55, 59, 34, 20], "desc": "Ищут путь к духу через любовь и отношения и в этом проходят глубокие трансформации — проживают внутреннюю смерть и возрождение.", "note": "до 2027"}, "juxtaposition": {"name": "Настроений", "gates": [55, 59, 9, 16], "desc": "Люди, живущие в своих настроениях и жаждущие глубины и истины; у них большой творческий потенциал, это творческие наставники."}, "left": {"name": "Духа", "gates": [55, 59, 9, 16], "desc": "Ищут и находят дух — и вместе с ним большую радость жизни — через творчество, хорошую еду и близкие отношения."}}, "56": {"quarter": "civilization", "right": {"name": "Законов 2", "gates": [56, 60, 3, 50], "desc": "Сильные рассказчики, вдохновляющие других своими идеалистическими взглядами и верованиями; их волшебство соткано из обещаний и мечтаний."}, "juxtaposition": {"name": "Стимуляции", "gates": [56, 60, 27, 28], "desc": "Охотно рискуют ради любого стимула, который даёт цель жизни; рассказчики, которым становится легче, когда они делятся своими историями."}, "left": {"name": "Отвлечения", "gates": [56, 60, 27, 28], "desc": "Привлекают внимание к себе и своим проектам живым, будоражащим общением, которое со стороны может выглядеть как отвлечение."}}, "57": {"quarter": "duality", "right": {"name": "Проникновения 3", "gates": [57, 51, 53, 54], "desc": "Интуитивно чуткие люди, способные различать тонкое; их ясность ведёт амбицию к новому началу и уменьшает наш страх перед завтрашним днём."}, "juxtaposition": {"name": "Интуиции", "gates": [57, 51, 62, 61], "desc": "Глубокие и вдохновляющие люди, которые интуицией, точными деталями, знанием и неожиданностью проникают в другого и доносят своё послание."}, "left": {"name": "Глашатая 2", "gates": [57, 51, 62, 61], "desc": "Интуитивные люди, несущие важные и вдохновляющие сведения, которых ждут другие; их нужно найти и попросить заговорить."}}, "58": {"quarter": "mutation", "right": {"name": "Служения 4", "gates": [58, 52, 18, 17], "desc": "Радость и изумление перед жизнью дают им силы оспаривать нормы и совершенствовать логический процесс, служащий обществу, — через идеи и формы."}, "juxtaposition": {"name": "Жизненности", "gates": [58, 52, 48, 21], "desc": "Полны явной жизненной силы и понимают, как важно решать, на что и на кого её тратить."}, "left": {"name": "Требований 2", "gates": [58, 52, 48, 21], "desc": "Хотят вложить силы в чужой проект или отождествиться с ним и оттачивают навыки, если получают взамен желаемое; лучшая защита для них — нападение."}}, "59": {"quarter": "duality", "right": {"name": "Спящего Феникса 3", "gates": [59, 55, 20, 34], "desc": "Мощные носители плодородия, стремящиеся «делать больше» ради будущего благополучия; им нужны близость и безопасность в отношениях."}, "juxtaposition": {"name": "Стратегии", "gates": [59, 55, 16, 9], "desc": "Превращают возможности в стратегии, ведущие к близости с другими; умеют соединять людей, которые подходят друг другу."}, "left": {"name": "Духа 2", "gates": [59, 55, 16, 9], "desc": "Уроки любви и чувственности превращаются у них в мудрость жизненного опыта; их тема — преображение связи любви и сексуальности через дух."}}, "60": {"quarter": "mutation", "right": {"name": "Законов 4", "gates": [60, 56, 50, 3], "desc": "Принимают ограничения, оценивая настоящее и возможные перемены, и всё же поддерживают традиционные ценности, на которых стоят законы, — вроде «не убий»."}, "juxtaposition": {"name": "Ограничений", "gates": [60, 56, 28, 27], "desc": "Находчивые люди, умеющие извлечь максимум из скрытого в ограничениях потенциала; ищут цель через риск и заботу о себе и других, проверяя каждую границу."}, "left": {"name": "Отвлечения 2", "gates": [60, 56, 28, 27], "desc": "Используют отвлечение как искусство, словно фокусники; выходят за пределы ограничений через яркость и рискованные поступки."}}, "61": {"quarter": "mutation", "right": {"name": "Майи 4", "gates": [61, 62, 32, 42], "desc": "Вдохновлённые и вдохновляющие мыслители, которым важно направлять ум на служение другим, пытаясь постичь непостижимое; ищут всеобщую истину в фактах и деталях."}, "juxtaposition": {"name": "Размышления", "gates": [61, 62, 50, 3], "desc": "Интеллектуалы, ищущие знание ради знания; их личные точные прозрения способны изменить привычные взгляды, из них выходят хорошие защитники."}, "left": {"name": "Затемнения 2", "gates": [61, 62, 50, 3], "desc": "Их вдохновенное знание может проявить детали всеобщих законов и принципов, которые иначе остались бы незамеченными."}}, "62": {"quarter": "civilization", "right": {"name": "Майи 2", "gates": [62, 61, 42, 32], "desc": "Сильные просветители, понимающие, что логика способна преображать и исцелять; создают и используют язык, чтобы назвать и оформить истину, спрятанную в деталях."}, "juxtaposition": {"name": "Деталей", "gates": [62, 61, 3, 50], "desc": "Умеют выражать мнения очень подробно; занимаясь законами и правилами, становятся хорошими защитниками и юристами."}, "left": {"name": "Затемнения", "gates": [62, 61, 3, 50], "desc": "Способны деталями и цифрами как ослепить, так и запутать; но когда неясные детали разобраны, из них может родиться необыкновенное открытие."}}, "63": {"quarter": "initiation", "right": {"name": "Сознания", "gates": [63, 64, 5, 35], "desc": "Смотрят дальше нужд — на то, зачем мы здесь, — сомневаясь в привычных схемах и проверяя их; в потоке жизни поднимаются над бесконечной жаждой нового опыта."}, "juxtaposition": {"name": "Сомнений", "gates": [63, 64, 26, 45], "desc": "Яркие, убеждённые и влиятельные скептики, умеющие «продать» свою позицию другим, когда им нужны логичные ответы, уравновешивающие опыт."}, "left": {"name": "Владычества", "gates": [63, 64, 26, 45], "desc": "Сильный ум, способный прийти к власти при любых обстоятельствах; сомнение и замешательство других могут становиться их инструментом влияния."}}, "64": {"quarter": "duality", "right": {"name": "Сознания 3", "gates": [64, 63, 35, 5], "desc": "Вдохновляют и помогают другим понять смысл их прошлого, проверяя опыт на соответствие привычным схемам и находя новые способы мыслить и понимать жизнь."}, "juxtaposition": {"name": "Замешательства", "gates": [64, 63, 45, 26], "desc": "Вдохновляющие летописцы и источники сведений, чья память укоренена в иерархиях рода и подвержена толкованиям и влиянию эго."}, "left": {"name": "Владычества 2", "gates": [64, 63, 45, 26], "desc": "Их толкование прошлого сильно действует на других; информация становится для них способом занять позицию силы и власти."}}}};
window.HM_PLANETS={"sun": {"name": "Солнце", "key": "жизненная сила", "text": "Солнце — главная энергия карты, её основной свет и тема всего воплощения. Ворота и линия, активированные Солнцем, описывают то, чем вы «являетесь» и что делаете в мире, — именно эту тему вы проживаете ярче всего. В Личности Солнце показывает, как вы сознательно несёте свой свет другим; в Дизайне — темы, которые книга связывает с наследием по линии отца. Это самая весомая активация в карте, поэтому на неё стоит смотреть в первую очередь.", "plain": "Через Солнце эта тема становится главной нотой вашей жизни — тем, что вы несёте в мир."}, "earth": {"name": "Земля", "key": "заземление и баланс", "text": "Земля всегда стоит напротив Солнца и работает с ним в паре: Солнце даёт свет, а Земля помогает воплотить его в теле и удержать равновесие. Ворота и линия Земли показывают, что даёт вам опору и устойчивость, на чём вы стоите. Книга связывает Землю с архетипом Матери и с началом Инь — мягким, удерживающим балансом. Когда вы живёте эту тему, проще чувствовать себя на своём месте и не терять почву под ногами.", "plain": "Через Землю эта тема становится вашей опорой — тем, что вас заземляет и уравновешивает."}, "moon": {"name": "Луна", "key": "движущая сила", "text": "Луна — то, что вами движет. Если Солнце задаёт содержание, то Луна даёт направление, силу и драйв, чтобы это содержание воплотилось. Ворота и линия Луны показывают, откуда берётся ваш внутренний мотив и что толкает вас вперёд. Луна также отражает свет: в этой теме другие видят вашу внутреннюю природу.", "plain": "Через Луну эта тема становится тем, что вами движет."}, "north_node": {"name": "Северный узел", "key": "будущее направление и окружение", "text": "Лунные узлы — не планеты, но влияют не меньше: они задают сцену, на которой разворачивается жизнь, и то, как вы воспринимаете окружающий мир. Северный узел — сцена зрелости: его тема всё сильнее звучит во второй половине жизни, примерно после 38–43 лет. Ворота и линия Северного узла описывают окружение и направление, в которых вы взрослеете и находите своё место. Переход к нему — это умение отпустить то, что больше не служит, сохранив то, что работает.", "plain": "Через Северный узел эта тема становится направлением и окружением вашей зрелой жизни."}, "south_node": {"name": "Южный узел", "key": "прошлое направление и окружение", "text": "Южный узел описывает сцену первой половины жизни — путь накопления опыта, пока вы ещё растёте и ищете себя. Его ворота и линия показывают, в каком окружении и через какие темы вы набираетесь опыта в молодости. Примерно к 38–43 годам эстафета переходит к Северному узлу, и это можно ощущать как вступление в настоящую взрослость. При этом опыт Южного узла не исчезает — он становится основой, на которую вы опираетесь дальше.", "plain": "Через Южный узел эта тема становится сценой, на которой вы набирались опыта в первой половине жизни."}, "mercury": {"name": "Меркурий", "key": "коммуникация и мышление", "text": "Меркурий отвечает за общение и расширение сознания — за потребность делиться тем, что вы понимаете. Ворота и линия Меркурия показывают, о чём вам важно говорить и что вы хотите донести до других. В Личности это осознанная потребность высказаться; в Дизайне тема тоже касается общения, но проявляется бессознательно — порой вы и сами не знаете, почему сказали человеку именно это. Книга связывает Меркурий с архетипом Старшего сына.", "plain": "Через Меркурий эта тема становится тем, о чём вам важно говорить и чем делиться."}, "venus": {"name": "Венера", "key": "ценности", "text": "Венера определяет ваши ценности и внутренний моральный кодекс — ощущение, что правильно, а что нет, в отношениях с людьми и миром. Ворота и линия Венеры показывают, на каких ценностях строится ваше взаимодействие с другими. С Венерой связаны также любовь и красота. Если действовать вопреки своей моральной ясности, это довольно быстро возвращается последствиями.", "plain": "Через Венеру эта тема становится вашей ценностью — тем, что вы считаете правильным."}, "mars": {"name": "Марс", "key": "незрелая энергия", "text": "Марс — энергия, которой ещё предстоит повзрослеть: сначала она может дремать, а затем, набрав обороты, вырываться за рамки. Ворота и линия Марса показывают, где в вас живёт такая сырая сила и где она поначалу может проявляться неловко или резко. С опытом и мудростью эта энергия находит верное применение и становится настоящим ресурсом. Книга отводит Марсу одну из ключевых ролей в личной трансформации.", "plain": "Через Марс эта тема становится вашей незрелой силой, которая взрослеет вместе с вами."}, "jupiter": {"name": "Юпитер", "key": "закон и защита", "text": "Юпитер — одна из самых сильных активаций после Солнца: он хранит ваш личный «закон», то есть то, что правильно именно для вас. Ворота и линия Юпитера показывают, следуя какому принципу вы оказываетесь под защитой и получаете поддержку. Когда вы живёте по этому закону, удача может быть очень щедрой. Но воспользоваться его щедростью можно, только если действительно следовать своему правилу.", "plain": "Через Юпитер эта тема становится вашим законом: следуя ей, вы получаете защиту и поддержку."}, "saturn": {"name": "Сатурн", "key": "дисциплина (судья)", "text": "Сатурн — строгий судья и учитель: он показывает, где вы встречаетесь с последствиями своих поступков. Ворота и линия Сатурна описывают область, в которой нарушение собственных ценностей и правил ощущается особенно болезненно. Похвалы от него ждать не стоит: если Сатурн вас не беспокоит, это знак, что вы живёте верно. Со временем по нему хорошо видно, насколько вы продвинулись.", "plain": "Через Сатурн эта тема становится областью, где вы учитесь дисциплине и видите последствия своих выборов."}, "uranus": {"name": "Уран", "key": "необычность, хаос и порядок", "text": "Уран отвечает за вашу необычность — то, чем вы непохожи на других. Ворота и линия Урана показывают, где вы проявляетесь нестандартно и вносите в привычный порядок что-то новое, иногда через хаос. Книга связывает Уран и с большими циклами жизни: субъективностью молодости, объективностью середины жизни и выходом за пределы себя в зрелости. Эту тему не нужно подгонять под норму — в ней ваша оригинальность.", "plain": "Через Уран эта тема становится вашей необычностью — тем, чем вы отличаетесь от других."}, "neptune": {"name": "Нептун", "key": "иллюзии и духовность", "text": "Нептун скрывает потенциал ворот за вуалью: тему, которую он активирует, трудно ясно увидеть и проконтролировать. Это может тревожить, ведь ум привык всё понимать, — а здесь легко обмануться или перегнуть палку, не заметив границ. Книга называет Нептун великим учителем сдачи: чем меньше вы пытаетесь им управлять, тем вернее его магия проявится сама. Ворота и линия Нептуна — это место, где лучше довериться, чем контролировать.", "plain": "Через Нептун эта тема окутана тайной — она раскрывается, когда вы перестаёте её контролировать."}, "pluto": {"name": "Плутон", "key": "истина и трансформация", "text": "Плутон поднимает на поверхность то, что скрыто в глубине, и несёт тему возрождения. Ворота и линия Плутона показывают, где в вашей жизни проходит глубокая трансформация и где вам приходится встретиться с правдой. Книга называет его тем, кто говорит правду, — даже если она неудобна. Эта тема меняется медленно, зато перемены через неё самые глубокие. Глубокий урок Плутона — найти свет в темноте.", "plain": "Через Плутон эта тема становится местом вашей глубокой трансформации и встречи с правдой."}};
window.HM_CENTERS_SIMPLE={"head": {"kind": "Центр давления", "theme": "Вдохновение, вопросы, ментальное давление", "function": "Темя — самый верхний центр, источник вдохновения. Он рождает вопросы, сомнения и желание понять. Сам по себе он ничего не делает: только задаёт вопрос, а ответ ищет ум. Это как зуд «почему так?», который не даёт покоя.", "defined": "У вас есть постоянный источник вопросов: определённые темы снова и снова занимают голову. Ум почти всегда работает, и это ваша природа, а не проблема. Ваши вопросы вдохновляют других и заставляют их думать. Главное — не спешить превращать каждую мысль в действие и не пытаться «выключить» голову.", "open": "Вопросы часто приходят к вам от других людей — и звучат в вас даже громче, чем у них. Легко начать решать чужие задачи и думать о том, что вас не касается. Зато вам доступна внутренняя тишина: мысли могут приходить и уходить. Учитесь отличать важные вопросы от шума и не принимайте решений из того, что просто «показалось интересным».", "false_self": "Ум ложного «я» хватается за любой вопрос как за личную задачу и требует немедленного ответа, даже если вопрос вообще не ваш. Он ищет, чем бы вдохновиться, бежит к тем, у кого «есть ответы», и строит решения на том, что просто показалось интересным.", "voices": ["Мне нужно срочно в этом разобраться", "У кого есть ответ на этот вопрос?", "Надо найти что-то вдохновляющее, иначе пусто", "О чём мне вообще следует думать?"], "wisdom": "Мудрость открытого Темени — различать, какое вдохновение действительно ценно, а что лишь ментальный шум, и кто вокруг вдохновляет, а кто приносит путаницу. Такой человек может наслаждаться вопросами и самим неизвестным, не требуя от себя немедленных ответов, и со временем становится проводником к по-настоящему важным вопросам.", "completely_open": "Без единой активации трудно понять, что по-настоящему интересно и на чём сосредоточиться; есть риск брать чужие интересы и ценности или выдумывать ответы под давлением. Когда давлению позволено проходить сквозь, открывается тонкое чутьё к чужим мыслям и к тому, кто пользуется умом эффективно.", "plain_defined": "В вашей голове почти всегда идёт работа: вопросы одного рода снова и снова просят ответа, и это нормально — так вы устроены. Не торопитесь превращать каждую идею в действие и делитесь вдохновением, когда его ждут.", "plain_open": "Многие вопросы, которые крутятся у вас в голове, пришли от других людей, и отвечать на все не обязательно. Позвольте мыслям приходить и уходить, а решения принимайте не из того, что «показалось интересным».", "practice": ["Чей это вопрос — мой или я подхватил его у кого-то рядом?", "Что изменится в моей жизни, если я так и не найду на него ответ?"], "detail": "Темя — один из двух центров давления (второй — Корень): оно давит сверху, требуя понять. Это давление уходит только в Аджну, где из вопроса рождается идея, а через неё — в Горло, где идея становится словами. Три связи Темени с Аджной книга соотносит с тремя взглядами во времени: осмыслить прошлый опыт, вникнуть в настоящее и проверить сомнением будущее. Определённое Темя всегда идёт вместе с определённой Аджной. Книга связывает центр с шишковидной железой."}, "ajna": {"kind": "Центр осознанности", "theme": "Ум, осмысление, мнения и концепции", "function": "Аджна — это ум: место, где вопросы превращаются в идеи, мнения и объяснения. Ум любит взвешивать «за» и «против» и легко путешествует между прошлым и будущим. Но у него нет своей силы, чтобы действовать. Поэтому ум хорош как советчик и исследователь, а не как тот, кто принимает решения.", "defined": "У вас устойчивый способ думать — своя постоянная точка зрения, через которую вы смотрите на всё. На ваш ум можно положиться, и чужие мнения сбивают его мало. Ловушка — путать уверенность ума с правотой и отдавать ему решения о жизни. Решения лучше доверять Авторитету — внутреннему ориентиру тела, а ум оставить для понимания и объяснения.", "open": "У вас нет одного закреплённого способа думать: вы легко перенимаете образ мыслей тех, кто рядом. Рядом с логиком рассуждаете логично, рядом с мечтателем — образами. Из-за этого с детства может казаться, что вы «недостаточно умны», и хочется изображать уверенность. На деле это гибкость: вы способны понять любую точку зрения, и спокойные «может быть» и «можно посмотреть и так» — ваша сила.", "false_self": "Ложное «я» открытой Аджны притворяется уверенным: держится за чужие концепции как за собственную истину и доказывает себе и другим, что у него есть твёрдое мнение. Оно же пытается выстроить мыслями всю жизнь и найти единственный правильный ответ, хотя открытый ум для этого не предназначен.", "voices": ["Я должен точно знать, как правильно", "Мне нужно выяснить, что делать со своей жизнью", "Лучше промолчу, а то решат, что я странный", "Я абсолютно уверен, что…"], "wisdom": "Мудрость открытой Аджны — понимать, какие концепции имеют реальную ценность, и видеть, кто действительно способен ответить на вопрос. Такой ум умеет отфильтровать множество возможностей, удерживать разные точки зрения, не присваивая ни одну, и показывать другим, как ум может сбивать с пути.", "completely_open": "При полностью открытых Темени и Аджне не на что опереться в организации мыслей: может казаться, что непонятно, о чём думать и есть ли в мышлении смысл, и ложное «я» охотно этим пользуется. Освоившись, такой человек наслаждается многообразием теорий, не привязываясь ни к одной, и по приглашению учится отличать полезные идеи.", "plain_defined": "Ваш ум думает в своём устойчивом стиле, и на его способ рассуждать можно положиться — как на инструмент, а не как на того, кто принимает решения. Делитесь мыслями, когда вас спрашивают, и помните, что ваша точка зрения — одна из многих.", "plain_open": "Ваш способ думать меняется в зависимости от того, кто рядом, поэтому вам не нужно изображать уверенность. «Может быть» — вполне достойный ответ, а решения пусть приходят из вашего Авторитета, а не из размышлений.", "practice": ["Где я сейчас изображаю уверенность, которой на самом деле нет?", "Чей способ рассуждать я перенял в этом разговоре?"], "detail": "Аджна — один из трёх центров осознанности и единственный, полностью отрезанный от моторов, поэтому ум сам ничего не воплощает. Сверху в неё входит давление Темени, снизу она передаёт мысли в Горло, где они становятся речью. Её связи образуют три способа мышления: логический (проверка закономерностей), абстрактный (осмысление прожитого опыта) и индивидуальный (внезапное знание). Типичный страх ума — тревога чего-то не знать или не понять. Книга связывает Аджну с гипофизом и зрительной корой."}, "throat": {"kind": "Центр манифестации", "theme": "Общение, выражение, действие, перемены", "function": "Горло — центр речи и действия. Сюда стремится энергия всех остальных центров, чтобы стать словом или поступком. Через Горло мы выражаем мысли, чувства, знание и проявляемся в мире. Сам центр энергии не даёт: говорить и действовать его заставляют те центры, с которыми он связан.", "defined": "У вас постоянный, узнаваемый голос — свой способ говорить и проявляться. В зависимости от того, с чем связано Горло, ваша речь окрашена мыслью, чувством, волей, откликом или ощущением себя. Если с Горлом связан мотор, вы можете действовать в любой момент, но это не значит, что нужно всегда. Слова лучше всего принимают, когда вы говорите вовремя, следуя своей Стратегии — правильному для вас способу вступать в дела.", "open": "Постоянного голоса нет: ваша манера речи меняется в зависимости от того, кто рядом. В компании может появляться сильное давление сказать хоть что-нибудь — перебить, удивить, заполнить паузу. Тогда слова выходят «не те», и потом хочется промолчать. Вам подходит говорить спонтанно и спокойно чувствовать себя в тишине: если дождаться подходящего момента или приглашения, всё нужное будет сказано.", "false_self": "Ложное «я» открытого Горла боится остаться незамеченным и делает всё, чтобы привлечь внимание: заполняет паузы, выходит вперёд, доказывает, что ему есть что сказать. Оно же тянет к действию ради действия — участвовать в чём угодно, лишь бы быть «делателем», даже если дело совсем не ваше.", "voices": ["Скажу хоть что-нибудь, тишина невыносима", "Меня вообще кто-нибудь замечает?", "Если я начну этот разговор, на меня обратят внимание", "Кем мне нужно стать, чтобы меня увидели?"], "wisdom": "Мудрость открытого Горла — распознавать, кто говорит и действует из своей сути, а кто нет, и находить общий язык с кем угодно. Со временем оно развивает очень широкий диапазон форм выражения и многое понимает о манифестации, не отождествляясь ни с одной её формой.", "completely_open": "Полностью открытое Горло встречается так же редко, как Горло со всеми 11 активациями: человек не знает заранее, что сказать или сделать, а детям с такой конфигурацией может понадобиться больше времени, чтобы научиться говорить, и их темп стоит уважать. Когда гибкость и непредсказуемость речи становятся комфортными, раскрывается умение отличать тех, кто говорит по сути.", "plain_defined": "У вас есть узнаваемый голос — свой способ говорить и проявляться, на который можно положиться. Важно не столько говорить больше, сколько говорить вовремя, — тогда вас слышат.", "plain_open": "Вам не нужно заполнять тишину или заслуживать внимание — оно приходит само, особенно когда вас приглашают. Позвольте себе говорить спонтанно и спокойно молчать, когда сказать нечего.", "practice": ["Я сейчас говорю, потому что есть что сказать, или чтобы меня заметили?", "Меня пригласили в этот разговор или я в него врываюсь?"], "detail": "Горло — самый сложный центр: у него 11 ворот, и каждые несут свой «голос» — от «я думаю» до «я хочу» и «я знаю». Оно может напрямую соединяться с шестью центрами; только Темя и Корень не имеют к нему прямого выхода. Первая функция Горла — общение, вторая — проявление в действии, которое возможно, лишь когда к Горлу подключён мотор (Сердце, Сакрал, Солнечное сплетение или, через другие центры, Корень). Книга называет его местом перемен и связывает со щитовидной и паращитовидными железами."}, "g": {"kind": "Центр идентичности и направления", "theme": "Любовь, идентичность, направление жизни", "function": "G-центр, или Центр Я, отвечает за ощущение себя, любовь и направление в жизни. Он как внутренний магнит, который притягивает к вам нужных людей, места и события. Он ведёт вас по своей дороге, даже если вы этого не замечаете. Здесь живёт ответ на вопросы «кто я?» и «куда я иду?».", "defined": "Вы устойчиво чувствуете, кто вы, и обычно не мучаетесь вопросом «кто я?». У вас есть своё направление, и вы можете вдохновлять других, показывая путь. Само направление происходит естественно — контролировать его не нужно. Ловушка — ждать, что все пойдут за вами, и навязывать свой образ тем, кто его легко перенимает.", "open": "У вас нет одного жёсткого образа себя: рядом с разными людьми вы немного разные. Это не изъян — вы здесь, чтобы пробовать и узнавать многое. Главное для вас — место: в правильном месте появляются правильные люди и направление. Прислушивайтесь, где вам хорошо, и будьте осторожны с теми, кто «знает, кем вам быть».", "false_self": "Ложное «я» открытого G без конца ищет любовь и направление и пытается умом выяснить, кто он такой. Оно примеряет чужие идентичности, гонится за званиями и титулами, принимает чужое направление за своё — и разочаровывается от бесконечных блужданий.", "voices": ["Кто я на самом деле?", "Куда мне пойти, чтобы наконец найти себя?", "С этим человеком я пойму, кто я", "Найду ли я здесь любовь?"], "wisdom": "Мудрость открытого G — тонко ценить место, культуру, идентичность и любовь, видеть, кто живёт своей подлинной жизнью, и быть прекрасным проводником для других. Отпустив поиск себя, такой человек может «влезть в любую шкуру» и с любовью подсказать направление.", "completely_open": "Полностью открытый G лишён ясной самоидентификации и врождённого чувства направления: можно чувствовать себя флюгером на ветру и искать подтверждения у других, что делает уязвимым для манипуляций. Освоившись со своей открытостью, такие люди обретают глубокое понимание человеческой природы, любви к себе и путей по жизни.", "plain_defined": "У вас есть устойчивое чувство себя и своего пути, даже если вы не можете его объяснить словами. Идите своей дорогой, но не ждите, что все пойдут за вами, — у других свои маршруты.", "plain_open": "Вам не нужно раз и навсегда отвечать на вопрос «кто я» — вы раскрываетесь по-разному в разных местах и с разными людьми. Доверяйте ощущению места: где вам хорошо, там появляются и нужные люди, и направление.", "practice": ["Как я чувствую себя в этом месте — и что это говорит о людях, которые меня сюда привели?", "Где я сейчас ищу себя в чужом отражении?"], "detail": "G-центр находится в середине бодиграфа; книга называет его домом Магнитного Монополя — «магнита», который только притягивает и прокладывает траекторию жизни. Восемь его ворот делятся на две группы: ворота любви (к себе, к телу, к людям, ко всему живому) и ворота роли и направления. У центра нет своей энергии и давления; когда он связан с Горлом, человек прямо выражает своё «я» и свой путь. Через связь с Сердцем любовь соединяется с силой воли. Книга связывает G-центр с печенью и кровью."}, "heart": {"kind": "Мотор", "theme": "Сила воли, ценность, материальный мир", "function": "Сердце, или Эго, — мотор силы воли. Его язык — «я хочу», «я могу», «моё». Оно помогает выживать в материальном мире: зарабатывать, договариваться, держать слово, заботиться о своих. Этот мотор работает рывками: мощное усилие, а потом нужен настоящий отдых.", "defined": "У вас есть постоянный доступ к силе воли: вы знаете себе цену и можете долго держаться намеченного. Вам подходит самому распоряжаться своим временем, ресурсами и отдыхом. Давайте только те обещания, которые действительно выполните, — это укрепляет самоуважение. Ловушка — требовать от других такой же воли и раздувать своё «я».", "open": "Своей устойчивой силы воли нет, и это нормально — вы не созданы, чтобы что-то доказывать и соревноваться. Рядом с волевыми людьми появляется заёмная решимость, которая исчезает, когда вы остаётесь одни. Отсюда круг: обещание, срыв, ещё более громкое обещание и чувство «я недостаточно хорош». Простое правило — не давать обещаний ни себе, ни другим: вам нечего доказывать.", "false_self": "Ложное «я» открытого Сердца всё время пытается доказать свою ценность и улучшить себя: даёт обещания, на которые не хватает воли, берётся за непосильное и сравнивает себя с другими. Каждая неудача становится поводом для новой, ещё более амбициозной попытки — и для самоосуждения.", "voices": ["Я должен доказать, что чего-то стою", "Почему я не могу так же, как они?", "Обещаю — на этот раз точно сделаю", "Пока не докажу, я недостаточно хорош"], "wisdom": "Мудрость открытого Сердца — видеть, у кого здоровая самооценка, а у кого нет, кто способен держать слово, а кто нет, и тонко чувствовать, чего на самом деле хотят люди. Такой человек понимает, что ему не нужно ни с кем соревноваться и никому ничего доказывать.", "completely_open": "Полностью открытому Сердцу трудно понять, что такое ценность и чем её измерять: чувство собственной важности колеблется от раздутого до почти нулевого, и человек уязвим для тех, кто обещает её повысить. Приняв, что ему нечего доказывать, он становится лучшим экспертом в оценке чьего-то слова, денежных вложений и личной силы.", "plain_defined": "У вас есть собственная сила воли, и вам важно самому распоряжаться своей жизнью. Обещайте только то, что действительно выполните, — так растут уважение к себе и доверие других.", "plain_open": "Вам ничего не нужно доказывать — ни себе, ни другим, и ваша ценность не зависит от выполненных обещаний. Прежде чем пообещать, остановитесь и спросите себя, откуда пришло это решение — изнутри или из желания выглядеть достойно.", "practice": ["Что я пытаюсь доказать этим обещанием — и кому?", "Это моя решимость или заёмная воля человека рядом?"], "detail": "Сердце — мотор: оно даёт энергию, но не решает, куда её направить, поэтому цели лучше поверять Авторитетом, а не умом. С его воротами книга связывает жизнь «племени» — семьи и сообщества: работу, сделки, взаимную поддержку, кров и еду. Через связь с Горлом воля может напрямую говорить и действовать, а через связь с G-центром соединяется с ощущением себя. Его ритм — усилие и полный отдых, в отличие от ровной ежедневной энергии Сакрала. Книга связывает его ворота с сердцем, желудком, вилочковой железой и жёлчным пузырём."}, "sacral": {"kind": "Мотор", "theme": "Жизненная сила, отклик, плодородие", "function": "Сакрал — главный мотор тела, источник жизненной силы. Он даёт энергию для работы, творчества, движения и продолжения жизни. Эта энергия раскрывается в ответ на то, что приходит снаружи: вопрос, предложение, ситуацию. Её голос — не слова, а телесное «угу» или «не-а», которое вырывается само.", "defined": "В вас каждый день вырабатывается новая порция энергии, и ей нужен выход в деле, которое по душе. Ваш надёжный ориентир — отклик: мгновенное телесное «да» или «нет» на то, что предлагает жизнь. Если взяться за дело, на которое было «да», хватит сил дойти до мастерства. Если браться за «надо» по указке ума, приходят раздражение, усталость и брошенные на полпути дела.", "open": "Своей постоянной рабочей энергии нет: она то приходит, то уходит. Рядом с энергичными людьми кажется, что сил больше, чем у всех, — и легко переработать, не заметив, когда пора остановиться. Вам подходит работать рывками, отдыхать больше других и ложиться спать до того, как навалилась усталость. Побыть одному — лучший способ сбросить чужую энергию, накопленную за день.", "false_self": "Ложное «я» открытого Сакрала не знает, когда достаточно. Оно путает заёмную энергию со своей и пытается доказать, что способно тянуть столько же, сколько Генераторы, — отсюда слишком много работы, обязательств и потраченных сил, пока тело не остановит человека истощением.", "voices": ["Ещё немного — силы же есть.", "Соглашусь, а то упущу шанс.", "Давайте я сделаю это за них.", "Чувство меры? Какое ещё чувство меры?"], "wisdom": "Когда человек перестаёт отождествляться с чужой силой и что-то себе доказывать, открытый Сакрал становится мудростью о жизненной силе. Он видит, у кого какая энергия, на что она годится и сколько её на самом деле, и может быть ценным советчиком для людей с определённым Сакралом. Его собственный ритм — работа и отдых в равновесии, без самоосуждения за непостоянство.", "completely_open": "Полностью открытый Сакрал не знает, на что направить энергию: она кажется рассеянной и притягивается то к одному, то к другому, а остановка нередко наступает только через полное истощение. Его потенциальная мудрость — понимание истинной меры жизненной силы и того, для чего предназначена та или иная энергия.", "plain_defined": "У вас есть ежедневный запас сил, который восстанавливается через сон, и лучше всего он расходуется на то, что вызывает в вас живое «да». Прислушивайтесь к первому телесному отклику — он точнее любых доводов ума.", "plain_open": "Энергия у вас приходит волнами, и часть ощущаемой бодрости вы берёте у людей вокруг. Отдыхайте до усталости, а не после, и спрашивайте себя, сколько на самом деле достаточно.", "practice": ["Что из сделанного сегодня было ответом на живое «да», а что — на «надо», и как после этого менялся уровень сил?", "В какой момент сегодня тело подсказало, что пора остановиться, и что произошло дальше?"], "detail": "Сакрал — единственный мотор, который может давать ровную энергию изо дня в день, если она тратится на то, на что был отклик; иначе приходят фрустрация и истощение. В нём девять ворот, и он может соединяться с Корнем, Селезёнкой, Солнечным сплетением, G-центром и Горлом. Определённый Сакрал делает человека Генератором, а прямая связь моторной энергии с Горлом — Манифестирующим Генератором. С этим центром связаны также сексуальность и границы в близости. Книга связывает его с половыми железами."}, "solarplexus": {"kind": "Мотор и центр осознанности", "theme": "Эмоции, желания, ясность во времени", "function": "Солнечное сплетение — центр эмоций, чувств и желаний. Он одновременно даёт силу действовать и помогает понимать. Здесь живут страсть, близость, сострадание, романтика и надежда. Эмоции идут волной: подъём сменяется спадом, и это естественный ритм.", "defined": "Ваши чувства движутся волной — от надежды к разочарованию, от радости к грусти, и часто без внешней причины. Поэтому в моменте нет полной ясности: на подъёме всё кажется лучше, на спаде — хуже. Это ваш Авторитет — внутренний способ принимать решения: важное нужно «переспать» и дождаться, пока чувство успокоится. Ясность узнаётся по тому, что решение больше не меняется вместе с настроением.", "open": "Вы сильно чувствуете эмоции других людей — порой даже ярче, чем они сами. Чужую грусть или раздражение легко принять за свою, а ум тут же придумает причину. Наедине с собой вы обычно спокойны и рассудительны. Полезно спрашивать себя: «Это моё чувство или я его уловил?» — и не принимать решений в чужой эмоциональной буре.", "false_self": "Ложное «я» открытого Солнечного сплетения делает всё возможное, чтобы избежать конфронтации и правды. Оно надевает маску приветливости, сглаживает углы и молчит о своих потребностях — пока накопленное не прорвётся вспышкой по ничтожному поводу.", "voices": ["Не стоит туда идти — вдруг будет конфликт.", "Промолчу, чтобы никого не расстроить.", "Улыбнусь и соглашусь — так меня точно примут.", "Немного приукрашу, лишь бы не было сцены."], "wisdom": "Когда человек перестаёт отождествляться с волнами и бояться решений, которые могут кому-то испортить настроение, открытый центр становится барометром эмоционального здоровья вокруг. Его трудно обмануть: он точно чувствует, что на самом деле переживает другой, и видит, кто движется к эмоциональной зрелости. Весь спектр чувств остаётся доступен ему как яркий опыт, но без власти над решениями.", "completely_open": "Полностью открытому Солнечному сплетению нечем фильтровать эмоциональную энергию: человек может путаться в своих чувствах, не понимать, чего желать и как обходиться с потребностями других, и считать, что с его эмоциональностью что-то не так. Его потенциальная мудрость — знать эмоциональные волны в самом чистом виде, без окраски.", "plain_defined": "Ваши чувства движутся волной, и на пике подъёма или спада ясно увидеть ситуацию нельзя. Дайте важным решениям время — верный ответ останется тем же и в хорошем, и в плохом настроении.", "plain_open": "Вы тонко чувствуете эмоции людей вокруг и часто переживаете их сильнее, чем они сами. Спрашивайте себя, чьё это чувство, и не принимайте решений только ради того, чтобы избежать неприятного разговора.", "practice": ["Как менялось моё отношение к одному и тому же решению за несколько дней — на подъёме и на спаде?", "Где сегодня моё молчание или согласие было способом избежать конфликта?"], "detail": "Солнечное сплетение — единственный центр, который одновременно и мотор, и центр осознанности; книга считает его самым молодым, ещё созревающим. Топливо ему даёт Корень, а с Сакралом, Сердцем и Горлом он соединяется напрямую. Его связи образуют три вида эмоциональных волн: племенную (о близости и поддержке), индивидуальную (о настроениях и страсти) и абстрактную (о желании пережить новое). Когда сплетение определено, оно всегда становится главным ориентиром для решений. Книга связывает центр с нервной системой, почками, лёгкими, поджелудочной и предстательной железами."}, "spleen": {"kind": "Центр осознанности", "theme": "Интуиция, здоровье, выживание в моменте", "function": "Селезёнка — это чутьё тела: инстинкт, интуиция и ощущение «хорошо мне или нет». Она заботится о здоровье и безопасности. Работает только здесь и сейчас и говорит тихо, один раз. Это как внезапное «не ходи туда» или «вот это — моё».", "defined": "У вас есть устойчивое чувство физического благополучия, и вам обычно легко побыть одному. Ваша интуиция говорит в моменте и не повторяет дважды: если не услышать сразу, сигнал уходит. Ловушка — позволить громкому уму заглушить тихий импульс: так чутьё со временем притупляется. Доверяйте первому ощущению и не принимайте здоровье как должное.", "open": "Вы усиливаете страхи и самочувствие окружающих, а наедине с собой можете чувствовать себя не вполне хорошо. Рядом с некоторыми людьми сразу становится спокойнее — и кажется, что они вам подходят. Так появляются привязанности к людям, работе и привычкам, которые давно не полезны. Учитесь встречать страхи по одному и не держаться за то, что лишь даёт ощущение безопасности.", "false_self": "Ложное «я» открытой Селезёнки держится за то, что вредно, лишь бы не лишиться ощущения безопасности. Оно избегает всего, что пугает, откладывает перемены и цепляется за людей и ситуации, рядом с которыми временно становится легче.", "voices": ["Лучше не рисковать — мне страшно.", "Завтра всё наладится, потерплю ещё.", "Не могу уйти: вдруг останусь без опоры?", "Не возьмусь — боюсь провала и критики."], "wisdom": "Со временем открытая Селезёнка обретает мудрость о здоровье: она чувствует, кому хорошо, а кому плохо, и что у человека вышло из равновесия, — таким даром обладают многие целители. Она умеет заботиться о себе, распознаёт, у кого интуиция работает, а у кого нет, и сама может стать очень интуитивной. Этот дар доступен, только когда человек перестаёт говорить «у меня» о том, что улавливает от других.", "completely_open": "Полностью открытая Селезёнка может потерять контакт со здоровыми страхами: человек то боится всего подряд, то не знает, чего бояться, и совершает рискованные поступки. При этом ей доступен самый широкий спектр инстинктивного знания, включая понимание того, как законы, ценности и предприимчивость защищают выживание будущих поколений.", "plain_defined": "Ваше тело подсказывает тихим мгновенным импульсом, что сейчас для вас хорошо, а что нет. Доверяйте этому первому «да» или «нет» сразу — второго предупреждения не будет.", "plain_open": "Рядом с некоторыми людьми вам становится спокойно и хорошо, но это ещё не значит, что они вам подходят. Не решайте сгоряча и спрашивайте себя, за что вы держитесь только из страха.", "practice": ["Был ли сегодня тихий мгновенный импульс, который заглушили доводы ума, — и что было потом?", "За что в моей жизни я держусь, хотя это уже не идёт мне на пользу?"], "detail": "Селезёнка — самый древний из трёх центров осознанности: она роднит нас со всем живым. Она не мотор, поэтому её сигнал не настаивает и легко тонет в голосе ума и эмоций. Каждые из её семи ворот несут свой древний страх выживания; если смотреть ему в лицо, он превращается в бдительность и осознанность. Селезёнка может соединяться с Корнем, Сакралом, Сердцем, G-центром и Горлом, а когда Сакрал и Солнечное сплетение открыты, она становится Авторитетом. Книга связывает её с лимфатической системой и иммунитетом."}, "root": {"kind": "Мотор и центр давления", "theme": "Давление, адреналин, движущая сила", "function": "Корень — центр давления и топлива для жизни. Он толкает начинать, торопиться, развиваться и справляться с трудностями. Это то, что мы называем стрессом или адреналином. В меру он даёт ощущение живости, а слишком много или слишком мало — выбивает из колеи.", "defined": "У вас свой постоянный способ справляться с давлением, поэтому чужая спешка трогает вас мало. Давление приходит импульсами: то включается мощный заряд, то затихает. Когда оно включено, его чувствуют и окружающие. Если направлять эту силу, следуя своей Стратегии и Авторитету, вы остаётесь спокойным даже в самых напряжённых ситуациях.", "open": "Вы впитываете и усиливаете давление окружающих — и хочется скорее от него избавиться. Вы спешите закрыть дела, но на месте одного тут же появляется другое. В напряжённой обстановке вы торопитесь больше всех, хотя сами никуда не спешили. Помогает простое: в момент давления сделать шаг назад, подышать и спросить себя, правда ли это нужно сделать прямо сейчас.", "false_self": "Ложное «я» открытого Корня всегда спешит освободиться от давления. Оно хватается за всё, что давит, стремится скорее закончить и мечтает о свободе «когда-нибудь потом» — но давление жить не исчезает, и колесо крутится всё быстрее.", "voices": ["Надо срочно с этим покончить.", "Нельзя терять ни минуты.", "Начну что-нибудь новое прямо сейчас.", "Отдохну, когда всё доделаю."], "wisdom": "Мудрость открытого Корня — различать, какое давление принадлежит вам, а какое нет, и видеть, у кого какой стресс. Он знает, сколько времени на самом деле потребует дело, когда уместно сверхусилие, а когда — покой, и может научить других обходиться с разными видами стресса.", "completely_open": "Полностью открытый Корень может испытывать весь спектр давления — от глубокой неподвижности и сосредоточенности до гиперактивности, — не понимая его природы, автоматически говорить «да» и спешить, пока система не начнёт сдавать. Природа становится для такого человека естественным местом покоя, где чужое давление проходит насквозь и успокаивается.", "plain_defined": "У вас есть собственный внутренний двигатель, который время от времени включается и толкает к делу. Направляйте этот напор через свою Стратегию и помните, что окружающие чувствуют ваш стресс сильнее, чем вам кажется.", "plain_open": "Вы легко подхватываете чужую спешку и начинаете торопиться, даже когда это не нужно. Позволяйте себе паузы, даже если ещё не всё сделано: давление никуда не денется, а силы сохранятся.", "practice": ["Что из сделанного сегодня было сделано в спешке только ради того, чтобы избавиться от давления?", "Чья это была спешка — моя или людей рядом, и как менялось моё состояние в одиночестве?"], "detail": "Корень — один из двух центров давления (второй — Темя) и одновременно мотор. Его энергия слишком сильна, чтобы идти прямо к Горлу, поэтому она проходит через Сакрал, Селезёнку или Солнечное сплетение. Связи с Сакралом задают ритм и способ действовать, с Селезёнкой — питают инстинкт выживания, с Солнечным сплетением — дают топливо эмоциям. Сам стресс книга не считает ни плохим, ни хорошим: важен баланс. Книга связывает Корень с надпочечниками и гормонами стресса."}};
(() => {
  if(window.HM_CORE_BOOK)Object.assign(window.HM_CORE_BOOK.centers,window.HM_CENTERS_SIMPLE);
  const X=window.HM_CROSSES,P=window.HM_PLANETS;
  const tag=(cls,t)=>`<span class="knowledge-tag ${cls}">${esc(t)}</span>`;
  const ANGLE_RU={right:'Правоугольный крест',juxtaposition:'Крест Джакстапозиции',left:'Левоугольный крест'};
  function crossOf(h){
    if(!h.profile)return null;
    const pick=(side,body)=>h.activations.find(x=>x.side===side&&x.body===body);
    const ps=pick('personality','sun'),pe=pick('personality','earth'),ds=pick('design','sun'),de=pick('design','earth');
    if(!ps||!pe||!ds||!de)return null;
    const first=+h.profile.split('/')[0],angle=h.profile==='4/1'?'juxtaposition':first>=5?'left':'right';
    const g=X.gates[ps.gate];if(!g)return null;
    const c=g[angle],calc=[ps.gate,pe.gate,ds.gate,de.gate];
    const matches=c.gates.join()===calc.join();
    return {angle,cross:c,calc,matches,quarter:X.quarters[g.quarter],ps,pe,ds,de};
  }
  window.HM_crossOf=crossOf;
  function crossSection(h){
    const r=crossOf(h);if(!r)return '';
    const gate=g=>`<button type="button" class="cross-gate" data-detail="gate:${g}">${g}</button>`;
    const pos=[['Солнце Личности',r.ps],['Земля Личности',r.pe],['Солнце Дизайна',r.ds],['Земля Дизайна',r.de]].map(([n,a])=>`<div class="cross-pos ${a.side}"><span>${n}</span>${gate(a.gate)}<small>${esc((GATE_NAME(a.gate)))}</small></div>`).join('');
    const ang=X.intro.angles[r.angle]||'';
    return `<section id="cross" class="reading-section deep-only"><div class="section-head"><h2>Инкарнационный крест</h2><span>${esc(ANGLE_RU[r.angle])}</span></div><p class="section-intro">${esc(X.intro.plain)}</p><div class="cross-card"><div class="eyebrow">${esc(ANGLE_RU[r.angle])}</div><h3>${esc(r.cross.name)}${r.cross.note?` <small>(${esc(r.cross.note)})</small>`:''}</h3><p class="cross-quartet">${r.calc.join(' / ')}</p><div class="cross-grid">${pos}</div><div class="interpretive-box">${tag('hd','Классика Human Design')}<p>${esc(r.cross.desc)}</p></div><div class="deep-block"><h4>${esc(r.quarter.name)}${r.quarter.theme?' — '+esc(r.quarter.theme):''}</h4><p>${esc(r.quarter.text)}</p><h4>Что такое крест</h4><p>${esc(X.intro.what)}</p><h4>${esc(ANGLE_RU[r.angle])}</h4><p>${esc(ang)}</p></div>${r.matches?'':`<div class="notice soft">Расчётные ворота креста (${r.calc.join(' / ')}) отличаются от четвёрки в указателе книги (${r.cross.gates.join(' / ')}). Сверьте карту с программой специалиста.</div>`}<p class="supporting">Крест — самый общий слой карты: он раскрывается со временем и только при жизни по своей Стратегии и Авторитету. Название и четвёрка ворот — по указателю книги Баннелл, раздел 8.</p></div></section>`;
  }
  const GATE_NAME=g=>{const b=window.HumanMatrixBook&&window.HumanMatrixBook.GATE_BOOK[g];return b?b.name:(HD_TEXT.gates[g]||[''])[0]};
  function planetsSection(h){
    const order=['sun','earth','moon','north_node','south_node','mercury','venus','mars','jupiter','saturn','uranus','neptune','pluto'];
    const fx=window.HM_FIX;
    const cell=(side,body)=>{const a=h.activations.find(x=>x.side===side&&x.body===body);if(!a)return '<td>—</td>';const f=fx?fx.fixOf(a):'';return `<td><button type="button" class="rail-gate" data-detail="gate:${a.gate}">${a.gate}.${a.line}</button>${f?` <span class="fix-mini ${f}">${f==='up'?'▲':f==='down'?'▽':'✶'}</span>`:''}</td>`};
    const rows=order.map(k=>P[k]?`<tr><th><strong>${esc(P[k].name)}</strong><span>${esc(P[k].key)}</span></th>${cell('design',k)}${cell('personality',k)}</tr><tr class="planet-text"><td colspan="3">${esc(P[k].text)}</td></tr>`:'').join('');
    return `<section id="planets" class="reading-section deep-only"><div class="section-head"><h2>Планеты и активации</h2><span>13 точек · два слоя</span></div><p class="section-intro">Каждые ворота в карте активированы конкретной планетой. Планета показывает, какую сферу жизни окрашивает тема ворот. ▲ — линия в экзальтации, ▽ — в падении, ✶ — обе полярности: эта сторона линии выражена в вашей карте сильнее. Падение — не ошибка, а другой корректный способ проживания.</p><table class="planets-table"><thead><tr><th>Планета</th><th>Дизайн</th><th>Личность</th></tr></thead><tbody>${rows}</tbody></table><p class="supporting">Здесь учтена только прямая фиксация планетой активации. Другие виды фиксации (через гармоничные ворота, композит и транзиты) пока не рассчитываются.</p></section>`;
  }
  const prevChart=chartCard;
  chartCard=function(h,options={}){
    let html=prevChart(h,options);const fx=window.HM_FIX;if(!fx||options.other||options.title)return html;
    for(const a of h.activations){const f=fx.fixOf(a);if(!f)continue;const label=bodyNames[a.body]||a.body;
      const needle=`aria-label="${esc(label)}: ворота ${a.gate}, линия ${a.line}">${a.gate}.${a.line}</button>`;
      html=html.split(needle).join(`aria-label="${esc(label)}: ворота ${a.gate}, линия ${a.line}, ${fx.FIX_LABEL[f]}">${a.gate}.${a.line}<span class="fix-mini ${f}">${f==='up'?'▲':f==='down'?'▽':'✶'}</span></button>`);}
    return html;
  };
  const prevPerson=personView;
  personView=function(){
    let html=prevPerson();const p=active(),c=calcFor(p);if(!p||!c.ready)return html;const h=c.hd;
    html=html.replace('<section id="channels"',crossSection(h)+'<section id="channels"');
    html=html.replace('<section id="activations"',planetsSection(h)+'<section id="activations"');
    html=html.replace('</nav>','<a class="deep-link" href="#cross">Крест</a><a class="deep-link" href="#planets">Планеты</a></nav>');
    return html;
  };
  function focusGraph(v){
    const [kind,key]=(v||'').split(':');
    const keys=new Set(HumanMatrixHD.CHANNELS.filter(ch=>kind==='gate'?ch.gates.includes(+key):kind==='center'?ch.centers.includes(key):false).map(ch=>ch.key));
    document.querySelectorAll('#content .bodygraph.v14').forEach(bg=>{
      bg.classList.toggle('has-focus',keys.size>0);
      bg.querySelectorAll('g[data-channel]').forEach(g=>g.classList.toggle('focus',keys.has(g.dataset.channel)));
      bg.querySelectorAll('.channel-skeleton path').forEach(p=>{const on=keys.has(p.dataset.key);p.classList.toggle('focus',on);p.setAttribute('stroke',on?'#9fb3c4':'#e6eaed');p.setAttribute('stroke-width',on?5:4.2);});
      bg.querySelectorAll('.map-target').forEach(t=>t.classList.toggle('picked',t.dataset.detail===v));
    });
  }
  const prevSel=selectDetail;
  selectDetail=function(v){prevSel(v);focusGraph(v);};
  renderContent();
})();
